const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',folders:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3z"/>',film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 4v16M17 4v16M3 9h4M3 15h4M17 9h4M17 15h4"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',arrow:'<path d="m9 18 6-6-6-6"/>',back:'<path d="m15 18-6-6 6-6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v5a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5zm-9 10 9 5 9-5M3 17l9 5 9-5"/>',type:'<path d="M4 7V4h16v3M12 4v16M8 20h8"/>',camera:'<rect x="2" y="4" width="20" height="16" rx="2"/><circle cx="12" cy="12" r="3"/>',play:'<path d="m8 5 11 7-11 7z"/>',check:'<path d="m5 12 5 5L20 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',sparkle:'<path d="m12 2 2 7 7 3-7 2-2 7-3-7-7-2 7-3z"/>',video:'<rect x="2" y="4" width="15" height="16" rx="2"/><path d="m17 9 5-3v12l-5-3"/>',screen:'<rect x="2" y="3" width="20" height="15" rx="2"/><path d="M8 22h8M12 18v4"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',save:'<path d="M4 3h14l3 3v15H3V3zm4 0v7h9V3M7 21v-8h10v8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>'};
function I(name,s=18){return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`}
function phone(){return `<div class="phone"><div class="notch"></div><div class="screen"><div class="phone-status"><span>9:41</span><span>▰ ◖ ▪</span></div><h4>任务</h4><div class="tabs"><span>进行中</span><span>已完成</span><span>已归档</span></div><div class="create">＋ 新建任务</div>${[['#edf3ff','设计产品首页','今天'],['#e6faf3','优化体验流程','明天'],['#fdf0e9','准备测试材料','4月20日'],['#ebefff','完成产品演示','4月22日']].map(([c,n,d])=>`<div class="task"><span class="dot" style="background:${c}"></span><div><b>${n}</b><small>项目任务 · 待进行</small></div><span class="taskdate">${d}</span></div>`).join('')}<div class="navbottom"><span>⌂<br>首页</span><b>▣<br>任务</b><span>◷<br>日历</span><span>☺<br>我的</span></div></div></div>`}
function sidebar(active='segments'){return `<aside class="sidebar"><a class="brand" href="project.html"><span class="brand-emblem"></span>AI Promo Studio</a><div class="workspace">创作空间</div><nav class="sidenav"><a class="nav-link ${active==='work'?'active':''}" href="project.html">${I('grid')}工作台</a><a class="nav-link ${active==='segments'?'active':''}" href="project.html">${I('folders')}我的项目</a><a class="nav-link ${active==='templates'?'active':''}" href="templates.html">${I('film')}模板中心</a><a class="nav-link ${active==='favorites'?'active':''}" href="templates.html#favorites">${I('star')}我的收藏</a><a class="nav-link" href="templates.html">${I('image')}素材库</a></nav><div class="sidebottom"><div class="side-card"><div class="mini-title">✦ 用 AI，让创作更简单</div><div class="mini-desc">让代码变成分镜，让创意变成视频。</div></div><a class="nav-link nav-optional" href="project.html">${I('settings')}设置</a><div class="account"><div class="avatar">L</div><div><b>我的工作空间</b><p>个人账户 · 创作者</p></div></div></div></aside>`}
function topBar(crumb){return `<header class="top"><div class="breadcrumbs"><a href="project.html">我的项目</a>${I('arrow',14)}<a href="project.html">StepFlow</a>${I('arrow',14)}<strong>${crumb}</strong></div><div class="topright"><span class="roundicon">${I('search')}</span><span class="roundicon">${I('bell')}</span><div class="avatar" style="width:29px;height:29px;font-size:11px">L</div></div></header>`}
function shell(content,active='segments',crumb='视频片段'){return `<div class="app">${sidebar(active)}<main class="main">${topBar(crumb)}<div class="content">${content}</div></main></div>`}
const segs=[['01','产品开场与品牌介绍','通过手机主界面呈现产品定位，建立第一印象','产品开场','5–7 秒','待录屏','v1'],['02','快速创建任务','突出任务创建流程简单、高效的核心体验','核心功能','10–15 秒','待录屏','v2'],['03','AI 智能分析','展示 AI 如何拆解任务并给出行动建议','AI 能力','12–18 秒','待录屏','v3'],['04','可视化进度追踪','通过数据看板展示任务进展及项目状态','数据展示','8–12 秒','可编辑','v4'],['05','成果展示与收尾','总结产品价值，以品牌画面结束宣传片','产品收尾','5–8 秒','待录屏','v5']];
function project(){const rows=segs.map(s=>`<div class="segcard"><span class="segnumber">${s[0]}</span><div class="segthumb ${s[6]}">${phone()}</div><div class="segdesc"><h3>${s[1]}</h3><p>${s[2]}</p><div class="meta"><span class="pill ${s[3]==='AI 能力'?'purple':''}">${s[3]}</span><span>${I('clock',13)} ${s[4]}</span><span class="pill ${s[5]==='可编辑'?'green':'amber'}">${s[5]}</span></div></div><a href="recording.html" class="details-link">查看详情 ${I('arrow',15)}</a></div>`).join('');return shell(`<div class="pagehead"><div><div class="eyebrow">PROJECT / StepFlow</div><h1>视频片段</h1><p>AI 已根据项目源码为你规划 5 个展示片段。打开片段查看录屏建议与编辑模板。</p></div><div class="actions"><button class="btn secondary" id="analyze">${I('sparkle')} 重新规划</button><a class="btn" href="recording.html">${I('plus')} 新建片段</a></div></div><div class="notice"><div><div class="notice-title">✦ 源码分析已完成</div><div class="notice-sub">已识别 8 个页面 · 5 项核心功能 · 生成 5 个视频片段</div></div><span class="noticebadge">查看分析结果 →</span></div><div class="sectionheader"><h2>全部片段 <small>（5）</small></h2><small>每个片段都可以单独录屏、编辑和保存</small></div><section class="seglist">${rows}</section>`,'segments','视频片段')}
function recording(){const steps=[['进入任务列表页面','打开 StepFlow，进入「任务」页面，确保列表正常加载。'],['点击「新建任务」','在列表顶部点击蓝色「新建任务」按钮，打开创建表单。'],['输入任务信息','填写任务名称、简短描述，并选择一个截止日期。'],['完成创建并展示结果','点击创建，等待成功提示，在任务列表停留约 2 秒。']];return shell(`<div class="pagehead"><div><div class="eyebrow"><a href="project.html" style="color:#6485d8">← 返回片段列表</a></div><h1>快速创建任务</h1><p>片段 02 / 05 · 目标：通过真实操作突出“快速创建任务”的便捷性</p></div><a class="btn secondary" href="editor.html">打开编辑器 ${I('arrow',15)}</a></div><div class="twocol"><section class="box guide"><div class="guidetitle"><span class="guide-icon">${I('video',18)}</span>录屏指导</div><p class="guideintro">跟随以下操作完成录制。你不需要剪辑原始录屏，上传后可在下一步调整镜头和时长。</p><div class="steps">${steps.map((s,i)=>`<div class="step"><span class="stepno">${i+1}</span><div class="steptext"><b>${s[0]}</b><p>${s[1]}</p></div></div>`).join('')}</div><div class="softnote"><span>💡</span><div><strong>录制前的小建议</strong>请使用测试账号，关闭通知、隐藏个人信息，录制时保持操作节奏自然。建议录制 12–18 秒，最终片段将裁剪到约 10–15 秒。</div></div></section><div class="rightcol"><section class="box" style="overflow:hidden"><div class="previewbox">${phone()}</div><div class="previewmeta"><h3>建议展示效果</h3><p>采用「功能聚焦」模板，正面展示手机屏幕，轻微推近以突出任务创建过程。</p><a class="btn" href="editor.html">${I('upload')} 上传录屏并进入编辑</a><div class="tinyline"><span>适配设备：iPhone / Android</span><span>1080 × 1920 推荐</span></div></div></section><div class="box" style="padding:20px 22px"><div class="sectionheader" style="margin-bottom:12px"><h2 style="font-size:13px">预计片段时长</h2><span class="pill">10–15 秒</span></div><div style="font-size:12px;color:#9ba8b9;line-height:1.8">建议先录制完整操作，再通过模板自动聚焦关键步骤。</div></div></div></div>`,'segments','录屏指导')}
function editor(){return `<div class="editor-app"><header class="editor-top"><div class="editor-title"><a href="recording.html" class="roundicon" aria-label="返回">${I('back')}</a><span style="height:26px;width:1px;background:#e8edf5"></span><b>快速创建任务</b><span class="pill" style="margin-left:5px">简洁模式</span></div><div class="actions"><span class="muted" style="font-size:11px;margin-right:12px">✓ 已自动保存</span><button class="btn secondary" style="padding:11px 15px" id="moreMode">专业模式</button><a href="project.html" class="btn">完成编辑 ${I('check',15)}</a></div></header><main class="edit-main"><div class="edit-head"><div><div class="eyebrow">片段 02 / 05</div><h1>视频预览</h1><p>轻量化编辑：选择需要调整的内容，其余由模板自动完成。</p></div><span class="recording-tag">${I('screen',14)} iPhone 17 Pro · 1080×1920</span></div><div class="stage"><span class="stage-label">实时预览 / 功能聚焦模板</span><span class="stage-time">1920 × 1080</span>${phone()}<div class="stage-caption"><strong id="caption">快速创建任务</strong><span>简单几步，让每个灵感高效落地</span></div></div><div class="transport"><span class="playbutton" id="play">${I('play',15)}</span><span class="time">00:05 / 00:15</span><div class="scrub"></div><span class="time">1.0×</span></div><div class="tools">${[['upload','替换录屏'],['layers','更换模板'],['type','修改文字'],['camera','调整镜头']].map(x=>`<button class="tool" onclick="openDrawer('${x[1]}')">${I(x[0])}${x[1]}</button>`).join('')}</div><div class="undereditor"><span>✦ 你也可以让 AI 帮你调整，例如：“手机转慢一点，字幕晚出现一秒”</span><button class="textlink" onclick="openDrawer('AI 快速修改')">试试 AI 微调 →</button></div></main><div class="modal-shade" onclick="closeDrawer()"></div><aside class="settingdrawer"><div class="drawerhead"><span id="drawerTitle">调整镜头</span><button style="background:transparent" onclick="closeDrawer()">${I('close')}</button></div><p id="drawerHelp">这里仅展示当前选择工具的选项，其他复杂参数默认收起。</p><div class="draweritem"><label id="controlLabel">参数</label><input id="controlInput" placeholder="输入要修改的内容" /></div><button class="btn" style="margin-top:25px;width:100%;justify-content:center" onclick="applyDrawer()">应用修改</button></aside></div>`}
let currentDrawer='';window.openDrawer=(name)=>{currentDrawer=name;document.querySelector('.modal-shade').classList.add('on');document.querySelector('.settingdrawer').classList.add('on');document.querySelector('#drawerTitle').textContent=name;let data={"替换录屏":["选择要上传的录屏文件，更新设备屏幕预览。","录屏素材路径（示意）"],"更换模板":["从推荐模板或我的收藏中选择你喜欢的镜头风格。","模板名称"],"修改文字":["只修改当前片段的字幕，不会影响其他片段。","视频主标题"],"调整镜头":["默认通过首尾关键帧自动补齐中间运动画面。","旋转角度 / 动画速度"],"AI 快速修改":["用自然语言描述你希望调整的效果。","想如何调整这段视频？"]};let d=data[name]||data['修改文字'];document.querySelector('#drawerHelp').textContent=d[0];document.querySelector('#controlLabel').textContent=d[1];const inp=document.querySelector('#controlInput');inp.value=name==='修改文字'?'快速创建任务':'';inp.placeholder=name==='AI 快速修改'?'例如：让手机旋转慢一点':'输入修改内容';};window.closeDrawer=()=>{document.querySelector('.modal-shade')?.classList.remove('on');document.querySelector('.settingdrawer')?.classList.remove('on')};window.applyDrawer=()=>{if(currentDrawer==='修改文字'){let v=document.querySelector('#controlInput').value;if(v)document.querySelector('#caption').textContent=v;}closeDrawer()};
const ts=[['Hero 产品开场','轻柔推进与设备展示，适合建立第一印象。','t1'],['功能聚焦镜头','突出手机屏幕操作，适合展示软件交互。','t2'],['360° 设备旋转','多角度展示设备与品牌视觉。','t3'],['双设备对比','适合展示不同设备上的一致体验。','t4'],['智能分析展示','让数据结果与产品能力成为画面中心。','t5'],['极简品牌收尾','品牌标题与价值主张，干净有记忆点。','t6']];
function templates(){let only=location.hash==='#favorites';let favorites=JSON.parse(localStorage.getItem('promo-favs')||'["Hero 产品开场","功能聚焦镜头"]');let cards=ts.filter(x=>!only||favorites.includes(x[0])).map(x=>`<div class="templatecard box"><div class="templateimage ${x[2]}">${phone()}</div><div class="templatebody"><div class="templaterow"><h3 class="templatename">${x[0]}</h3><button class="star ${favorites.includes(x[0])?'active':''}" onclick="toggleFav('${x[0]}')">★</button></div><div class="templatedesc">${x[1]}</div><div class="templaterow"><span class="pill">真实 3D 设备</span><a href="editor.html" class="textlink">应用模板 →</a></div></div></div>`).join('');return shell(`<div class="pagehead"><div><div class="eyebrow">CREATIVE ASSETS</div><h1>${only?'我的收藏':'视频模板中心'}</h1><p>选择适合的镜头风格。好的设计收藏起来，下次使用更快捷。</p></div></div><div class="actions" style="margin-bottom:26px"><a href="templates.html" class="smallfilter ${!only?'active':''}">全部模板</a><a href="templates.html#favorites" class="smallfilter ${only?'active':''}">★ 我的收藏</a></div><div class="templategrid">${cards||'<p class="empty">收藏夹还是空的，去模板中心看看吧。</p>'}</div>`,'templates','模板中心')}
window.toggleFav=(name)=>{let arr=JSON.parse(localStorage.getItem('promo-favs')||'["Hero 产品开场","功能聚焦镜头"]');arr=arr.includes(name)?arr.filter(a=>a!==name):[...arr,name];localStorage.setItem('promo-favs',JSON.stringify(arr));document.querySelector('#root').innerHTML=templates()};
let page=document.body.dataset.page;document.querySelector('#root').innerHTML=page==='recording'?recording():page==='editor'?editor():page==='templates'?templates():project();window.onhashchange=()=>{if(page==='templates')document.querySelector('#root').innerHTML=templates()};
